export type GetMembersData = {
    body?: never;
    headers?: {
        /**
         * Response language: vi (Vietnamese, default) or en (English) / Ngôn ngữ phản hồi
         */
        'Accept-Language'?: 'vi' | 'en';
    };
    path?: never;
    query?: {
        /**
         * Page number (1-based) / Số trang (bắt đầu từ 1)
         */
        page?: number;
        /**
         * Page size / Số lượng bản ghi mỗi trang
         */
        size?: number;
        /**
         * Sort column / Cột cần sắp xếp
         */
        sortBy?: string;
        /**
         * Sort direction (ASC/DESC) / Hướng sắp xếp (ASC/DESC)
         */
        sortDirection?: string;
        /**
         * Approval period from (YYYY-MM-DD): date the member became a General Member; members without an approval date are excluded / Kỳ duyệt từ: ngày chuyển thành hội viên thường; hội viên chưa có ngày duyệt bị loại
         */
        aprvFromDt?: string;
        /**
         * Approval period to, inclusive (YYYY-MM-DD) / Kỳ duyệt đến (bao gồm)
         */
        aprvToDt?: string;
        /**
         * Field searched by searchText (default MBR_NO) / Trường tìm kiếm (mặc định mã hội viên): MBR_NO member code, SGDN_MBR_NO SGDN member code, LGN_ID login ID, MBR_NM member name, TELNO phone, EML_ADDR email, ORGNZ_NM company name, MST_NO enterprise code
         */
        searchField?: 'MBR_NO' | 'SGDN_MBR_NO' | 'LGN_ID' | 'MBR_NM' | 'TELNO' | 'EML_ADDR' | 'ORGNZ_NM' | 'MST_NO';
        /**
         * Search text, partial match on searchField / Từ khoá, khớp một phần theo searchField
         */
        searchText?: string;
        /**
         * Member grade / Hạng hội viên: T Temporary / Tạm thời, G General / Thường, F Full / Chính thức, DELETED deleted members / hội viên đã xoá (Show Deleted Members). Without DELETED, deleted members are excluded
         */
        mbrGrdCds?: Array<'T' | 'G' | 'F' | 'DELETED'>;
        /**
         * Member type / Loại hội viên (MBR_TYPE_CD): P Individual / Cá nhân, F Foreigner / Người nước ngoài, O Organization / Tổ chức
         */
        mbrTypeCds?: Array<'P' | 'F' | 'O'>;
        /**
         * Status / Trạng thái: PENDING_APPROVAL chờ duyệt, SUPPLEMENT_REQUESTED yêu cầu bổ sung, REJECTED từ chối, ACTIVE hoạt động, LOCKED bị khoá (status L or 5 wrong passwords / sai mật khẩu 5 lần)
         */
        sttsCds?: Array<'PENDING_APPROVAL' | 'SUPPLEMENT_REQUESTED' | 'REJECTED' | 'ACTIVE' | 'LOCKED'>;
        /**
         * Membership / Phí hội viên: PAID paid / đã nộp, EXEMPT exempt / miễn phí (both with a currently valid membership period / có kỳ hội viên còn hiệu lực), NONE no currently valid membership period / không có kỳ hội viên còn hiệu lực
         */
        mbrshpPayCds?: Array<'PAID' | 'EXEMPT' | 'NONE'>;
        /**
         * Legacy account status (ACTIVE, LOCKED) - use sttsCds / Trạng thái tài khoản cũ - dùng sttsCds
         */
        acntSttsCds?: Array<'ACTIVE' | 'LOCKED'>;
        /**
         * Legacy member classification / Phân loại hội viên cũ
         */
        mbrClsCds?: Array<'PENDING_APPROVAL' | 'SUPPLEMENT_REQUESTED' | 'PENDING_PAYMENT' | 'VERIFIED' | 'REJECTED' | 'CANCELLED'>;
        /**
         * Legacy approval stage / Giai đoạn phê duyệt cũ
         */
        atrzStages?: Array<'NOT_RECEIVED' | 'REQUESTED' | 'IN_PROGRESS' | 'APPROVED' | 'REJECTED' | 'SUPPLEMENT_REQUESTED'>;
        /**
         * Re-application: Y = an earlier round was sent back or rejected, N = first applications only / Hồ sơ nộp lại
         */
        reappliedYn?: 'Y' | 'N';
        /**
         * Raw member status / Trạng thái hội viên gốc (MBR_STTS_CD)
         */
        mbrSttsCds?: Array<'P' | 'U' | 'S' | 'R' | 'C' | 'L' | 'D'>;
        /**
         * Legacy: member or assignee name keyword - use searchField=MBR_NM / Từ khoá tên (cũ)
         */
        mbrNm?: string;
        /**
         * Legacy: organization name keyword - use searchField=ORGNZ_NM / Từ khoá tên tổ chức (cũ)
         */
        orgnzNm?: string;
        /**
         * Legacy: phone keyword - use searchField=TELNO / Từ khoá số điện thoại (cũ)
         */
        telno?: string;
        /**
         * Legacy: member code keyword - use searchField=MBR_NO / Từ khoá mã hội viên (cũ)
         */
        mbrNo?: string;
        /**
         * Legacy: email keyword - use searchField=EML_ADDR / Từ khoá email (cũ)
         */
        emlAddr?: string;
        /**
         * Legacy: registration date from (YYYY-MM-DD) / Ngày đăng ký từ (cũ)
         */
        regFromDt?: string;
        /**
         * Legacy: registration date to, inclusive (YYYY-MM-DD) / Ngày đăng ký đến (cũ)
         */
        regToDt?: string;
    };
    url: '/api/v1/members';
};

